import{_ as e,c as r,o as t,ae as i}from"./chunks/framework.CHDT0Kbg.js";const u=JSON.parse('{"title":"隱私與資料","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/privacy.md","filePath":"zh-TW/guide/privacy.md","lastUpdated":1795170900000}'),o={name:"zh-TW/guide/privacy.md"};function l(n,a,h,c,s,d){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="隱私與資料" tabindex="-1">隱私與資料 <a class="header-anchor" href="#隱私與資料" aria-label="Permalink to &quot;隱私與資料&quot;">​</a></h1><p>哪些內容留在你的 Mac 上，哪些情況需要連網。</p><h2 id="保存在本機" tabindex="-1">保存在本機 <a class="header-anchor" href="#保存在本機" aria-label="Permalink to &quot;保存在本機&quot;">​</a></h2><p>歷史、書籤、目前分頁、下載紀錄與 Cookie 都保存在本機。沒有帳戶，也沒有雲端同步。無痕視窗（⌘⇧N）不會寫入歷史與工作階段。</p><h2 id="什麼時候會連網" tabindex="-1">什麼時候會連網 <a class="header-anchor" href="#什麼時候會連網" aria-label="Permalink to &quot;什麼時候會連網&quot;">​</a></h2><ul><li>開啟你造訪的網站，這是理所當然的。</li><li>啟用了廣告訂閱時，更新訂閱規則。更新失敗也會沿用已儲存的規則。</li><li>下載你主動要求的使用者腳本或檔案。</li></ul><h2 id="權限由你決定" tabindex="-1">權限由你決定 <a class="header-anchor" href="#權限由你決定" aria-label="Permalink to &quot;權限由你決定&quot;">​</a></h2><p>鏡頭和麥克風按網站記住：你可以允許一個網站、拒絕另一個。定位與通知由 macOS 系統管理。彈窗預設只放行你允許的網站。</p><h2 id="磁碟上的檔案" tabindex="-1">磁碟上的檔案 <a class="header-anchor" href="#磁碟上的檔案" aria-label="Permalink to &quot;磁碟上的檔案&quot;">​</a></h2><p>Persim 只會讀取你在系統檔案面板中選擇、或明確授權過的資料夾，授權情況可以在設定中查看和撤銷。</p><h2 id="聯絡我們" tabindex="-1">聯絡我們 <a class="header-anchor" href="#聯絡我們" aria-label="Permalink to &quot;聯絡我們&quot;">​</a></h2><p>關於隱私的問題：<strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong>。</p>',12)])])}const m=e(o,[["render",l]]);export{u as __pageData,m as default};
